+  id: number;
+  title: string;
+  tags: string[];
+  due?: string;
+  status: Status;
+  createdAt: string;
+  completedAt?: string;
+};
+
+type Database = { nextId: number; tasks: Task[] };
+
+const databaseFile = process.env.TASKBOARD_FILE || ".taskboard.json";
+
+function fail(message: string): never {
+  console.error(message);
+  process.exit(1);
+}
+
+function isDate(value: string): boolean {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
+  const [year, month, day] = value.split("-").map(Number);
+  const date = new Date(year, month - 1, day);
+  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
+}
+
+function today(): string {
+  const date = new Date();
+  const pad = (value: number) => String(value).padStart(2, "0");
+  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
+}
+
+async function load(): Promise<Database> {
+  const file = Bun.file(databaseFile);
+  if (!(await file.exists())) return { nextId: 1, tasks: [] };
+  let data: unknown;
+  try {
+    data = await file.json();
+  } catch {
+    fail("Malformed task database.");
+  }
+  if (!data || typeof data !== "object" || !Array.isArray((data as Database).tasks) ||
+      !Number.isSafeInteger((data as Database).nextId) || (data as Database).nextId < 1) {
+    fail("Malformed task database.");
+  }
+  const db = data as Database;
+  for (const task of db.tasks) {
+    if (!task || !Number.isSafeInteger(task.id) || typeof task.title !== "string" ||
+        !Array.isArray(task.tags) || (task.status !== "open" && task.status !== "done") ||
+        typeof task.createdAt !== "string" || (task.due !== undefined && !isDate(task.due))) {
+      fail("Malformed task database.");
+    }
+  }
+  return db;
+}
+
+async function save(db: Database): Promise<void> {
+  const temporary = `${databaseFile}.tmp-${process.pid}-${Date.now()}`;
+  try {
+    await Bun.write(temporary, `${JSON.stringify(db, null, 2)}\n`);
+    await Bun.write(temporary, Bun.file(temporary));
+    await Bun.file(temporary).exists();
+    await Bun.spawn(["mv", temporary, databaseFile]).exited;
+  } catch {
+    try { await Bun.spawn(["rm", "-f", temporary]).exited; } catch { /* best effort */ }
+    fail("Unable to save task database.");
+  }
+}
+
+function options(args: string[], allowed: string[]): Record<string, string> {
+  const result: Record<string, string> = {};
+  for (let index = 0; index < args.length; index += 2) {
+    const flag = args[index];
+    const value = args[index + 1];
+    if (!flag?.startsWith("--") || !allowed.includes(flag) || value === undefined || result[flag] !== undefined) {
+      fail("Invalid command arguments.");
+    }
+    result[flag] = value;
+  }
+  return result;
+}
+
+function taskId(value: string | undefined): number {
+  if (!value || !/^\d+$/.test(value)) fail("Task ID must be a positive integer.");
+  const id = Number(value);
+  if (!Number.isSafeInteger(id) || id < 1) fail("Task ID must be a positive integer.");
+  return id;
+}
+
+const [command, ...args] = process.argv.slice(2);
+const db = await load();
+let output: unknown;
+
+if (command === "add") {
+  const input = options(args, ["--title", "--tags", "--due"]);
+  const title = input["--title"]?.trim();
+  if (!title) fail("A non-empty --title is required.");
+  if (input["--due"] && !isDate(input["--due"])) fail("Invalid due date.");
+  const tags = [...new Set((input["--tags"] || "").split(",").map(tag => tag.trim().toLowerCase()).filter(Boolean))];
+  const task: Task = { id: db.nextId++, title, tags, status: "open", createdAt: new Date().toISOString() };
+  if (input["--due"]) task.due = input["--due"];
+  db.tasks.push(task);
+  await save(db);
+  output = task;
+} else if (command === "list") {
+  const input = options(args, ["--status", "--tag", "--overdue"]);
+  if (input["--status"] && input["--status"] !== "open" && input["--status"] !== "done") fail("Invalid status.");
+  if (input["--overdue"] && !isDate(input["--overdue"])) fail("Invalid overdue date.");
+  const tag = input["--tag"]?.trim().toLowerCase();
+  output = db.tasks.filter(task =>
+    (!input["--status"] || task.status === input["--status"]) &&
+    (!tag || task.tags.includes(tag)) &&
+    (!input["--overdue"] || (task.status === "open" && task.due !== undefined && task.due < input["--overdue"]))
+  ).sort((a, b) => a.id - b.id);
+} else if (command === "done" || command === "delete") {
+  if (args.length !== 1) fail("Expected exactly one task ID.");
+  const id = taskId(args[0]);
+  const index = db.tasks.findIndex(task => task.id === id);
+  if (index < 0) fail("Task not found.");
+  if (command === "done") {
+    const task = db.tasks[index];
+    if (task.status === "open") {
+      task.status = "done";
+      task.completedAt = new Date().toISOString();
+      await save(db);
+    }
+    output = task;
+  } else {
+    const [task] = db.tasks.splice(index, 1);
+    await save(db);
+    output = task;
+  }
+} else if (command === "stats") {
+  if (args.length) fail("stats accepts no arguments.");
+  const open = db.tasks.filter(task => task.status === "open");
+  output = { total: db.tasks.length, open: open.length, done: db.tasks.length - open.length, overdue: open.filter(task => task.due && task.due < today()).length };
+} else {
+  fail("Unknown command.");
+}
+
+console.log(JSON.stringify(output));
