+import { afterEach, expect, test } from "bun:test";
+
+const db = `/tmp/taskboard-cli-${process.pid}.json`;
+const run = async (...args: string[]) => {
+  const proc = Bun.spawn(["bun", "run", "src/cli.ts", ...args], { env: { ...process.env, TASKBOARD_FILE: db }, stdout: "pipe", stderr: "pipe" });
+  return { code: await proc.exited, out: await new Response(proc.stdout).text() };
+};
+
+afterEach(async () => { await Bun.spawn(["rm", "-f", db]).exited; });
+
+test("adds, filters, completes, and reports tasks", async () => {
+  expect((await run("add", "--title", " First ", "--tags", "Work,work, Urgent", "--due", "2020-01-01")).code).toBe(0);
+  expect((await run("add", "--title", "Second")).code).toBe(0);
+  expect(JSON.parse((await run("list", "--tag", "WORK")).out)).toHaveLength(1);
+  expect(JSON.parse((await run("list", "--overdue", "2020-01-02")).out)).toHaveLength(1);
+  expect((await run("done", "1")).code).toBe(0);
+  expect(JSON.parse((await run("stats")).out)).toMatchObject({ total: 2, open: 1, done: 1, overdue: 0 });
+});
+
+test("rejects bad input without creating a database", async () => {
+  expect((await run("add", "--title", "", "--due", "2020-02-30")).code).not.toBe(0);
+  expect(await Bun.file(db).exists()).toBe(false);
+});
